mapper.select:
SELECT m.PORTFOLIO_ID portfolioId, n.PORTFOLIO_NAME portfolioName, n.VDATE, n.MDATE, n.PORTFOLIO_TYPE portfolioType, n.PROFIT_TYPE profitType , y.OPEN_TYPE openType , y.RAISE_TYPE raiseType , y.INVEST_NATURE investNature FROM
RSK_RULE_PORTFOLIO m
RSK_PORTFOLIO_PACKAGE_DTL m
inner join PTL_PORTFOLIO n on m.PORTFOLIO_ID=n.PORTFOLIO_ID inner join PA_PTL_PORTFOLIO y on m.PORTFOLIO_ID=y.PORTFOLIO_ID
m.RULE_ID=#{ptlBagId}
m.PTL_BAG_ID=#{ptlBagId}
and n.MDATE > CURRENT_DATE
and (n.PORTFOLIO_NAME LIKE CONCAT(CONCAT('%',#{portfolioName}),'%') or n.PORTFOLIO_ID LIKE CONCAT(CONCAT('%',#{portfolioName}),'%'))
and n.PROFIT_TYPE = #{profitType}
and y.OPEN_TYPE = #{openType}
and y.RAISE_TYPE = #{raiseType}
and y.INVEST_NATURE = #{investNature}
and n.PORTFOLIO_TYPE = #{portfolioType}
